from nokia_nom_open_api_client import (AlarmSearchQueryRequest, AlarmSearchFilter,
                                       AlarmSearchCriteria, AlarmUpdateRequest,
                                       AlarmSearchListCriteria)

from taf.nms.nom.schemas.fm.alarm_search_page_response import AlarmSearchPageResponse
from taf.nms.nom.schemas.fm.alarm_search_page_response import Alarm

import nokia_nom_open_api_client.models
from nokia_nom_open_api_client.models import AlarmSearchPageResponse as ASPR


class PatchedAlarmSearchPageResponse(ASPR):
    # Disable raising ValueError exception when no alarms matching to the set filters.
    # Otherwise Alarms schema in nom_2007_openapi.yaml has to be modified
    # (each time new spec version is provided) to accept None as value by setting 'nullable: true'
    @ASPR.alarms.setter
    def alarms(self, alarms):
        self._alarms = alarms

    # Disable raising ValueError exception when multiple filter criteria or
    # multiple condition criteria in filter criteria are set.
    # Otherwise AlarmSearchQueryRequest schema in nom_2007_openapi.yaml has to be modified
    # (each time new spec version is provided) to accept None as value by setting 'nullable: true'
    @ASPR.next.setter
    def next(self, next):
        self._next = next


nokia_nom_open_api_client.models.AlarmSearchPageResponse = PatchedAlarmSearchPageResponse


class FM(object):
    def __init__(self, api_client):
        """
        :param DefaultApi api_client:
        """
        self.api_client = api_client

    def get_alarms_from_integrated_ne(self, integrated_id, filters, active):
        integrated_id_filter = {
            "attribute_name": 'integratedId',
            "operator": 'EQ',
            "attribute_value": integrated_id
        }
        active_alarms_filter = {
            "attribute_name": 'alarmStatus',
            "operator": 'EQ',
            "attribute_value": 'active'
        }
        default_filter = [integrated_id_filter]
        if active:
            default_filter.append(active_alarms_filter)
        filters = self._get_all_filters(default_filter, filters)
        relational_condition = self._get_relational_condition(filters=filters)
        alarm_search_query_request = self._get_alarm_search_query_request(relational_condition=relational_condition)
        response = self._fetch_alarms(alarm_search_query_request)
        return AlarmSearchPageResponse.from_object_dict(response)

    def get_alarms(self, filters):
        all_alarms_filter = {
            "attribute_name": 'severity',
            "operator": 'IN',
            "values": ["critical", "major", "minor", "warning", "indeterminate"]
        }
        default_filter = [all_alarms_filter]
        relational_condition = self._get_relational_condition(filters=filters) if filters else None
        list_condition = self._get_list_condition(filters=default_filter)
        alarm_search_query_request = self._get_alarm_search_query_request(relational_condition=relational_condition,
                                                                          list_condition=list_condition)
        response = self._fetch_alarms(alarm_search_query_request)
        return AlarmSearchPageResponse.from_object_dict(response)

    def get_active_alarms(self, filters):
        active_alarms_filter = {
            "attribute_name": 'alarmStatus',
            "operator": 'EQ',
            "attribute_value": 'active'
        }
        default_filter = [active_alarms_filter]
        filters = self._get_all_filters(default_filter, filters)
        relational_condition = self._get_relational_condition(filters=filters)
        alarm_search_query_request = self._get_alarm_search_query_request(relational_condition=relational_condition)
        response = self._fetch_alarms(alarm_search_query_request)
        return AlarmSearchPageResponse.from_object_dict(response)

    def get_historical_alarms(self, filters):
        historical_alarms_filter = {
            "attribute_name": 'alarmStatus',
            "operator": 'EQ',
            "attribute_value": 'terminated'
        }
        default_filter = [historical_alarms_filter]
        filters = self._get_all_filters(default_filter, filters)
        relational_condition = self._get_relational_condition(filters=filters)
        alarm_search_query_request = self._get_alarm_search_query_request(relational_condition=relational_condition)
        response = self._fetch_alarms(alarm_search_query_request)
        return AlarmSearchPageResponse.from_object_dict(response)

    @staticmethod
    def _get_all_filters(default_filter, filters=None):
        return default_filter + (filters or [])

    def _fetch_alarms(self, alarm_search_query_request):
        return self.api_client.api_fm_v1_alarm_search_post(alarm_search_query_request=alarm_search_query_request)

    @staticmethod
    def _get_alarm_search_query_request(relational_condition=None, range_condition=None, list_condition=None):
        return AlarmSearchQueryRequest(
            filter_model=[AlarmSearchFilter(
                relational_condition=relational_condition,
                list_condition=list_condition,
                range_condition=range_condition
            )])

    @staticmethod
    def _get_list_condition(filters):
        return [AlarmSearchListCriteria(
            attribute_name=f["attribute_name"],
            operator=f["operator"],
            values=f["values"]) for f in filters]

    @staticmethod
    def _get_relational_condition(filters):
        return [AlarmSearchCriteria(
            attribute_name=f["attribute_name"],
            operator=f["operator"],
            attribute_value=f["attribute_value"]) for f in filters]

    def get_alarm_details(self, alarm_dn, system_alarm_id):
        response = self.api_client.api_fm_v1_alarms_dn_system_alarm_id_get(alarm_dn, system_alarm_id)
        return Alarm.from_object_dict(response)

    def acknowledge_alarm(self, alarm_dn, system_alarm_id):
        alarm_update_request = AlarmUpdateRequest(state_change_type="acknowledge")
        return self._change_alarms_state(alarm_dn, system_alarm_id, alarm_update_request)

    def reject_alarm(self, alarm_dn, system_alarm_id):
        alarm_update_request = AlarmUpdateRequest(state_change_type="unacknowledge")
        return self._change_alarms_state(alarm_dn, system_alarm_id, alarm_update_request)

    def cancel_alarm(self, alarm_dn, system_alarm_id):
        alarm_update_request = AlarmUpdateRequest(state_change_type="cancel")
        return self._change_alarms_state(alarm_dn, system_alarm_id, alarm_update_request)

    def _change_alarms_state(self, alarm_dn, system_alarm_id, alarm_update_request):
        return self.api_client.api_fm_v1_alarms_dn_system_alarm_id_post(alarm_dn, system_alarm_id, alarm_update_request)
